const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--font-render-hinting=none']
  });

  const page = await browser.newPage();

  await page.setViewport({ width: 1600, height: 2263, deviceScaleFactor: 2 });

  const filePath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(filePath, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for charts to render
  await page.waitForTimeout(2000);

  // Force all reveals visible
  await page.evaluate(() => {
    document.querySelectorAll('.reveal').forEach(el => el.classList.add('visible'));
    document.querySelectorAll('.animate').forEach(el => {
      el.style.animationDelay = '0s';
      el.style.animationDuration = '0s';
    });
  });

  await page.waitForTimeout(500);

  // Hide menu for screenshot
  await page.evaluate(() => {
    const menu = document.querySelector('.viz-menu');
    if (menu) menu.style.display = 'none';
  });

  await page.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
    clip: { x: 0, y: 0, width: 1600, height: 2263 },
    omitBackground: false
  });

  console.log('Poster rendered to /app/output/final_poster.png');

  // Get file size
  const fs = require('fs');
  const stats = fs.statSync('/app/output/final_poster.png');
  console.log('File size:', (stats.size / 1024 / 1024).toFixed(2), 'MB');

  await browser.close();
})();

