      *, *::before, *::after { animation: none !important; transition: none !important; }
      .reveal { opacity: 1; transform: none; }
    }

    @media print {
      body { background: white !important; color: black !important; width: auto; height: auto; overflow: visible; }
      .viz-menu { display: none !important; }
      .card { break-inside: avoid; border: 1px solid #ddd; box-shadow: none; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }

    @media (max-width: 375px) { body { overflow-x: hidden; } }

    /* ===== MENU ===== */
    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px); transition: all 0.2s;
    }
    .viz-menu-toggle:hover { background: var(--surface-hover); }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 200px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s; backdrop-filter: blur(16px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    *:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 2px;
      border-radius: 4px;
    }

    .sr-only {
      position: absolute; width: 1px; height: 1px;
      overflow: hidden; clip: rect(0,0,0,0);
    }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>
      </span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg><span>Download PNG</span></button>
      <button onclick="window.print()"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg><span>Print / PDF</span></button>
    </div>
  </div>

  <main id="main-content" role="main">
    <div class="poster-wrapper">

      <!-- HEADER -->
      <header class="poster-header animate">
        <div class="badge">Artificial Analysis Intelligence Index v4.0</div>
        <h1>Frontier AI Models Compared<br><span class="accent">Intelligence</span> · <span class="teal">Speed</span> · <span class="amber">Cost</span></h1>
        <p class="subtitle">A data-driven comparison of the top 10 frontier AI language models — there is no single "best" model. The right choice depends on your priorities.</p>
      </header>

      <!-- HERO STATS -->
      <section class="hero-stats animate delay-1" aria-label="Key metrics">
        <div class="hero-stat" role="img" aria-label="Top intelligence score: 57">
          <div class="value" data-count="57">57</div>
          <div class="label">Top Intelligence</div>
          <div class="context">Gemini 3.1 Pro &amp; GPT-5.4 tied</div>
        </div>
        <div class="hero-stat" role="img" aria-label="Fastest speed: 206 tokens per second">
          <div class="value" data-count="206" data-suffix=" tok/s">206 tok/s</div>
          <div class="label">Fastest Output</div>
          <div class="context">gpt-oss-120B (high) leads</div>
        </div>
        <div class="hero-stat" role="img" aria-label="Price range factor: 33 times">
          <div class="value"><span data-count="33" data-suffix="×">33×</span></div>
          <div class="label">Price Spread</div>
          <div class="context">$0.30 to $10.00 per 1M tokens</div>
        </div>
      </section>

      <!-- THREE CHARTS ROW -->
      <section class="charts-row animate delay-2" aria-label="Model comparison charts">
        <div class="chart-panel">
          <div class="section-title"><span class="dot dot-blue"></span> Intelligence Ranking</div>
          <div class="chart-container" role="img" aria-label="Horizontal bar chart of intelligence scores: Gemini 3.1 Pro 57, GPT-5.4 57, Claude Opus 4.6 53, Muse Spark 52, Claude Sonnet 4.6 52, GLM-5.1 51, Grok 4.20 49, Gemini 3 Flash 46, DeepSeek V3.2 42, Nemotron 3 36, gpt-oss-120B 33">
            <canvas id="intelligenceChart"></canvas>
            <div class="sr-only">Intelligence scores: Gemini 3.1 Pro Preview 57, GPT-5.4 57, Claude Opus 4.6 53, Muse Spark 52, Claude Sonnet 4.6 52, GLM-5.1 51, Grok 4.20 49, Gemini 3 Flash 46, DeepSeek V3.2 42, NVIDIA Nemotron 3 36, gpt-oss-120B 33</div>
          </div>
        </div>
        <div class="chart-panel">
          <div class="section-title"><span class="dot dot-teal"></span> Output Speed</div>
          <div class="chart-container" role="img" aria-label="Horizontal bar chart of output speed in tokens per second">
            <canvas id="speedChart"></canvas>
            <div class="sr-only">Speed: gpt-oss-120B 206, Nemotron 3 193, Grok 4.20 162, Gemini 3 Flash 149, Gemini 3.1 Pro 129, GPT-5.4 72, Claude Sonnet 4.6 48, GLM-5.1 40, Claude Opus 4.6 40, DeepSeek V3.2 31</div>
          </div>
        </div>
        <div class="chart-panel">
          <div class="section-title"><span class="dot dot-amber"></span> Price per 1M Tokens</div>
          <div class="chart-container" role="img" aria-label="Horizontal bar chart of pricing from $0.30 to $10.00 per million tokens">
            <canvas id="priceChart"></canvas>
            <div class="sr-only">Price: gpt-oss-120B $0.30, DeepSeek V3.2 $0.30, Nemotron 3 $0.40, Gemini 3 Flash $1.10, GLM-5.1 $2.10, Grok 4.20 $3.00, Gemini 3.1 Pro $4.50, GPT-5.4 $5.60, Claude Sonnet 4.6 $6.00, Claude Opus 4.6 $10.00</div>
          </div>
        </div>
      </section>

      <!-- TRADEOFF BUBBLE CHART (HERO) -->
      <section class="tradeoff-section animate delay-3" aria-label="Trade-off analysis">
        <div class="section-title"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 8v8M8 12h8"/></svg> The Intelligence–Speed–Cost Trade-Off</div>
        <div class="tradeoff-panel">
          <div class="chart-container" role="img" aria-label="Bubble chart plotting intelligence score on Y axis versus output speed on X axis, with bubble size representing cost. Shows that faster and cheaper models tend to be less intelligent, while the most intelligent models are slower and more expensive.">
            <canvas id="tradeoffChart"></canvas>
          </div>
        </div>
      </section>

      <!-- INSIGHTS ROW -->
      <section class="insights-row animate delay-4" aria-label="Key trade-off insights">
        <div class="insight-card">
          <div class="insight-label"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg> Best Intelligence</div>
          <div class="insight-model">Gemini 3.1 Pro &amp; GPT-5.4</div>
          <div class="insight-detail">Tied at 57 — but $4.50–$5.60/1M tokens</div>
        </div>
        <div class="insight-card">
          <div class="insight-label"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 1v22M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg> Best Value</div>
          <div class="insight-model">gpt-oss-120B (high)</div>
          <div class="insight-detail">206 tok/s · $0.30 — but ranks last in intelligence (33)</div>
        </div>
        <div class="insight-card">
          <div class="insight-label"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/></svg> Balanced Pick</div>
          <div class="insight-model">Gemini 3 Flash</div>
          <div class="insight-detail">Score 46 · 149 tok/s · $1.10 — strong middle ground</div>
        </div>
        <div class="insight-card">
          <div class="insight-label"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/></svg> Premium Tier</div>
          <div class="insight-model">Claude Opus 4.6 (max)</div>
          <div class="insight-detail">Score 53 · 40 tok/s · $10.00 — slowest &amp; most expensive</div>
        </div>
      </section>

      <!-- FOOTER -->
      <footer class="poster-footer animate delay-5">
        <div class="methodology">
          <strong style="color: var(--text);">Methodology:</strong> The AA Intelligence Index v4.0 aggregates 10 independent evaluations — GDPval-AA, τ²-Bench, Terminal-Bench Hard, SciCode, AA-LCR, AA-Omniscience, IFBench, Humanity's Last Exam, GPQA Diamond, CritPt — spanning coding, agentic tasks, reasoning, knowledge, and instruction following.
        </div>
        <div class="source">
          Data: <strong>artificialanalysis.ai</strong><br>
          AA Intelligence Index v4.0
        </div>
      </footer>
    </div>
  </main>

  <script>
    // === Menu ===
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === Theme ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      var icon = document.getElementById('themeIcon');
      var label = document.getElementById('themeLabel');
      if (icon) icon.innerHTML = t === 'dark'
        ? '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>'
        : '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>';
      if (label) label.textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === Scroll Reveal ===
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });
    setTimeout(function() { document.querySelectorAll('.reveal').forEach(function(el) { el.classList.add('visible'); }); }, 500);

    // === Number Counter ===
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count);
        var prefix = el.dataset.prefix || '';
        var suffix = el.dataset.suffix || '';
        var start = performance.now();
        var duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1);
          var eased = 1 - Math.pow(1 - p, 3);
          el.textContent = prefix + Math.round(target * eased).toLocaleString() + suffix;
          if (p < 1) requestAnimationFrame(tick);
        })(start);
      });
    }
    var counterEl = document.querySelector('[data-count]');
    if (counterEl) {
      var cObs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
      }, { threshold: 0.3 });
      cObs.observe(counterEl);
    }

    // === Download PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = 'frontier-ai-models-compared.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    // === Chart.js Charts ===
    var chartsBuilt = false;

    var MODELS_INTEL = ['Gemini 3.1 Pro', 'GPT-5.4', 'Claude Opus 4.6', 'Muse Spark', 'Claude Sonnet 4.6', 'GLM-5.1', 'Grok 4.20', 'Gemini 3 Flash', 'DeepSeek V3.2', 'Nemotron 3', 'gpt-oss-120B'];
    var INTEL_SCORES = [57, 57, 53, 52, 52, 51, 49, 46, 42, 36, 33];

    var MODELS_SPEED = ['gpt-oss-120B', 'Nemotron 3', 'Grok 4.20', 'Gemini 3 Flash', 'Gemini 3.1 Pro', 'GPT-5.4', 'Claude Sonnet 4.6', 'GLM-5.1', 'Claude Opus 4.6', 'DeepSeek V3.2'];
    var SPEED_VALS = [206, 193, 162, 149, 129, 72, 48, 40, 40, 31];

    var MODELS_PRICE = ['Claude Opus 4.6', 'Claude Sonnet 4.6', 'GPT-5.4', 'Gemini 3.1 Pro', 'Grok 4.20', 'GLM-5.1', 'Gemini 3 Flash', 'Nemotron 3', 'DeepSeek V3.2', 'gpt-oss-120B'];
    var PRICE_VALS = [10.00, 6.00, 5.60, 4.50, 3.00, 2.10, 1.10, 0.40, 0.30, 0.30];

    function getThemeColors() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      return {
        isDark: isDark,
        text: isDark ? '#e6edf3' : '#0f172a',
        textSec: isDark ? '#8b949e' : '#64748b',
        grid: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.04)',
        blue: isDark ? '#58a6ff' : '#2563eb',
        teal: isDark ? '#2dd4bf' : '#0d9488',
        amber: isDark ? '#fbbf24' : '#d97706',
        surface: isDark ? '#161b22' : '#ffffff',
        blueFaded: isDark ? 'rgba(88,166,255,0.15)' : 'rgba(37,99,235,0.12)',
        tealFaded: isDark ? 'rgba(45,212,191,0.15)' : 'rgba(13,148,136,0.12)',
        amberFaded: isDark ? 'rgba(251,191,36,0.15)' : 'rgba(217,119,6,0.12)',
      };
    }

    function buildCharts() {
      if (typeof Chart === 'undefined') return;
      var c = getThemeColors();

      // Destroy existing
      if (window.chartIntel) { try { window.chartIntel.destroy(); } catch(e) {} }
      if (window.chartSpeed) { try { window.chartSpeed.destroy(); } catch(e) {} }
      if (window.chartPrice) { try { window.chartPrice.destroy(); } catch(e) {} }
      if (window.chartTradeoff) { try { window.chartTradeoff.destroy(); } catch(e) {} }

      var commonScaleX = {
        ticks: { color: c.textSec, font: { size: 11, family: 'Inter' } },
        grid: { color: c.grid },
        border: { display: false }
      };
      var commonScaleY = {
        ticks: { color: c.textSec, font: { size: 10, family: 'Inter' }, padding: 4 },
        grid: { display: false },
        border: { display: false }
      };

      // Intelligence chart
      var intelColors = INTEL_SCORES.map(function(s) {
        if (s >= 55) return c.blue;
        if (s >= 50) return isDark(c) ? 'rgba(88,166,255,0.6)' : 'rgba(37,99,235,0.6)';
        if (s >= 45) return isDark(c) ? 'rgba(88,166,255,0.4)' : 'rgba(37,99,235,0.4)';
        return isDark(c) ? 'rgba(88,166,255,0.25)' : 'rgba(37,99,235,0.25)';
      });

      window.chartIntel = new Chart(document.getElementById('intelligenceChart'), {
        type: 'bar',
        data: {
          labels: MODELS_INTEL,
          datasets: [{
            data: INTEL_SCORES,
            backgroundColor: intelColors,
            borderRadius: 3,
            barPercentage: 0.7,
            categoryPercentage: 0.85
          }]
        },
        options: {
          indexAxis: 'y',
