              grid: { color: c.grid },
              border: { display: false }
            },
            y: commonScaleY
          },
          layout: { padding: { right: 8 } }
        }
      });

      // Speed chart
      var speedColors = SPEED_VALS.map(function(s) {
        if (s >= 180) return c.teal;
        if (s >= 120) return isDark(c) ? 'rgba(45,212,191,0.6)' : 'rgba(13,148,136,0.6)';
        if (s >= 60) return isDark(c) ? 'rgba(45,212,191,0.4)' : 'rgba(13,148,136,0.4)';
        return isDark(c) ? 'rgba(45,212,191,0.25)' : 'rgba(13,148,136,0.25)';
      });

      window.chartSpeed = new Chart(document.getElementById('speedChart'), {
        type: 'bar',
        data: {
          labels: MODELS_SPEED,
          datasets: [{
            data: SPEED_VALS,
            backgroundColor: speedColors,
            borderRadius: 3,
            barPercentage: 0.7,
            categoryPercentage: 0.85
          }]
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: {
              enabled: true, padding: 10, cornerRadius: 6,
              titleFont: { size: 12, family: 'Inter' },
              bodyFont: { size: 12, family: 'Inter' },
              callbacks: { label: function(ctx) { return ctx.raw + ' tok/s'; } }
            }
          },
          scales: {
            x: {
              min: 0, max: 230,
              ticks: { color: c.textSec, font: { size: 10, family: 'Inter' }, stepSize: 50 },
              grid: { color: c.grid },
              border: { display: false }
            },
            y: commonScaleY
          },
          layout: { padding: { right: 8 } }
        }
      });

      // Price chart
      var priceColors = PRICE_VALS.map(function(p) {
        if (p >= 5) return c.amber;
        if (p >= 2) return isDark(c) ? 'rgba(251,191,36,0.6)' : 'rgba(217,119,6,0.6)';
        if (p >= 1) return isDark(c) ? 'rgba(251,191,36,0.4)' : 'rgba(217,119,6,0.4)';
        return isDark(c) ? 'rgba(251,191,36,0.25)' : 'rgba(217,119,6,0.25)';
      });

      window.chartPrice = new Chart(document.getElementById('priceChart'), {
        type: 'bar',
        data: {
          labels: MODELS_PRICE,
          datasets: [{
            data: PRICE_VALS,
            backgroundColor: priceColors,
            borderRadius: 3,
            barPercentage: 0.7,
            categoryPercentage: 0.85
          }]
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: {
              enabled: true, padding: 10, cornerRadius: 6,
              titleFont: { size: 12, family: 'Inter' },
              bodyFont: { size: 12, family: 'Inter' },
              callbacks: { label: function(ctx) { return '$' + ctx.raw.toFixed(2) + ' / 1M tokens'; } }
            }
          },
          scales: {
            x: {
              min: 0, max: 12,
              ticks: {
                color: c.textSec, font: { size: 10, family: 'Inter' },
                callback: function(v) { return '$' + v; }
              },
              grid: { color: c.grid },
              border: { display: false }
            },
            y: commonScaleY
          },
          layout: { padding: { right: 8 } }
        }
      });

      // === TRADEOFF BUBBLE CHART ===
      var bubbleData = [
        { name: 'Gemini 3.1 Pro', intel: 57, speed: 129, price: 4.50 },
        { name: 'GPT-5.4', intel: 57, speed: 72, price: 5.60 },
        { name: 'Claude Opus 4.6', intel: 53, speed: 40, price: 10.00 },
        { name: 'Muse Spark', intel: 52, speed: 55, price: 3.50 },
        { name: 'Claude Sonnet 4.6', intel: 52, speed: 48, price: 6.00 },
        { name: 'GLM-5.1', intel: 51, speed: 40, price: 2.10 },
        { name: 'Grok 4.20', intel: 49, speed: 162, price: 3.00 },
        { name: 'Gemini 3 Flash', intel: 46, speed: 149, price: 1.10 },
        { name: 'DeepSeek V3.2', intel: 42, speed: 31, price: 0.30 },
        { name: 'Nemotron 3', intel: 36, speed: 193, price: 0.40 },
        { name: 'gpt-oss-120B', intel: 33, speed: 206, price: 0.30 }
      ];

      var bubbleColors = [
        c.blue, c.blue,
        'rgba(188,140,255,0.9)',
        isDark(c) ? 'rgba(139,92,246,0.7)' : 'rgba(124,58,237,0.7)',
        'rgba(188,140,255,0.7)',
        isDark(c) ? 'rgba(100,180,255,0.6)' : 'rgba(37,99,235,0.5)',
        c.teal,
        c.teal,
        c.amber,
        c.amber,
        c.amber
      ];

      window.chartTradeoff = new Chart(document.getElementById('tradeoffChart'), {
        type: 'bubble',
        data: {
          datasets: bubbleData.map(function(d, i) {
            return {
              label: d.name,
              data: [{ x: d.speed, y: d.intel, r: Math.max(6, Math.sqrt(d.price) * 7) }],
              backgroundColor: bubbleColors[i],
              borderColor: 'rgba(255,255,255,0.2)',
              borderWidth: 1,
              hoverBorderWidth: 2,
              hoverBorderColor: '#fff'
            };
          })
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: {
              enabled: true, padding: 12, cornerRadius: 8,
              titleFont: { size: 13, family: 'Inter', weight: '600' },
              bodyFont: { size: 12, family: 'Inter' },
              callbacks: {
                title: function(items) { return bubbleData[items[0].datasetIndex].name; },
                label: function(ctx) {
                  var d = bubbleData[ctx.datasetIndex];
                  return [
                    'Intelligence: ' + d.intel,
                    'Speed: ' + d.speed + ' tok/s',
                    'Price: $' + d.price.toFixed(2) + '/1M tokens'
                  ];
                }
              }
            }
          },
          scales: {
            x: {
              title: {
                display: true, text: 'Output Speed (tokens/sec) →',
                color: c.textSec, font: { size: 12, family: 'Inter', weight: '500' },
                padding: { top: 8 }
              },
              min: 10, max: 230,
              ticks: { color: c.textSec, font: { size: 11, family: 'Inter' }, stepSize: 50 },
              grid: { color: c.grid },
              border: { display: false }
            },
            y: {
              title: {
                display: true, text: '↑ Intelligence Score',
                color: c.textSec, font: { size: 12, family: 'Inter', weight: '500' },
                padding: { bottom: 8 }
              },
              min: 28, max: 62,
              ticks: { color: c.textSec, font: { size: 11, family: 'Inter' }, stepSize: 5 },
              grid: { color: c.grid },
              border: { display: false }
            }
          },
          layout: { padding: { top: 10, right: 16, bottom: 4, left: 8 } }
        },
        plugins: [{
          id: 'bubbleLabels',
          afterDatasetsDraw: function(chart) {
            var ctx2 = chart.ctx;
            ctx2.save();
            ctx2.font = '600 11px Inter';
            ctx2.textAlign = 'center';
            ctx2.fillStyle = c.textSec;
            chart.data.datasets.forEach(function(dataset, i) {
              var meta = chart.getDatasetMeta(i);
              if (meta.data[0]) {
                var pt = meta.data[0];
                var d = bubbleData[i];
                var labelY = pt.y - pt.options.radius - 6;
                var shortName = d.name.replace(' Preview', '').replace(' (max)', '').replace(' (high)', '').replace(' (xhigh)', '').replace(' 0309 v2', '');
                ctx2.fillText(shortName, pt.x, labelY);
              }
            });
            ctx2.restore();
          }
        }, {
          id: 'sizeLegend',
          afterDraw: function(chart) {
            var ctx2 = chart.ctx;
            var area = chart.chartArea;
            ctx2.save();
            ctx2.font = '500 10px Inter';
            ctx2.fillStyle = c.textSec;
            ctx2.textAlign = 'left';

            var legendX = area.right - 130;
            var legendY = area.bottom - 50;

            ctx2.fillText('Bubble size = cost', legendX, legendY);
            ctx2.fillStyle = c.textSec;
            ctx2.globalAlpha = 0.5;
            ctx2.beginPath();
            ctx2.arc(legendX + 8, legendY + 18, 4, 0, Math.PI * 2);
            ctx2.fill();
            ctx2.beginPath();
            ctx2.arc(legendX + 28, legendY + 18, 8, 0, Math.PI * 2);
            ctx2.fill();
            ctx2.beginPath();
            ctx2.arc(legendX + 56, legendY + 18, 14, 0, Math.PI * 2);
            ctx2.fill();

            ctx2.globalAlpha = 1;
            ctx2.font = '400 9px Inter';
            ctx2.fillStyle = c.textSec;
            ctx2.fillText('$0.30', legendX - 2, legendY + 36);
            ctx2.fillText('$3', legendX + 22, legendY + 36);
            ctx2.fillText('$10', legendX + 46, legendY + 36);

            ctx2.restore();
          }
        }]
      });

      chartsBuilt = true;
    }

    function isDark(c) {
      return document.documentElement.classList.contains('theme-dark');
    }

    function onThemeChange() {
      chartsBuilt = false;
      buildCharts();
    }

    window.addEventListener('load', function() {
      setTimeout(function() {
        buildCharts();
        window.dispatchEvent(new Event('resize'));
      }, 200);
    });
  </script>
</body>
</html>

