        { name: 'Muse Spark', intel: 52, speed: 55, price: 3.50 },
        { name: 'Claude Sonnet 4.6', intel: 52, speed: 48, price: 6.00 },
        { name: 'GLM-5.1', intel: 51, speed: 40, price: 2.10 },
        { name: 'Grok 4.20', intel: 49, speed: 162, price: 3.00 },
        { name: 'Gemini 3 Flash', intel: 46, speed: 149, price: 1.10 },
        { name: 'DeepSeek V3.2', intel: 42, speed: 31, price: 0.30 },
        { name: 'Nemotron 3', intel: 36, speed: 193, price: 0.40 },
        { name: 'gpt-oss-120B', intel: 33, speed: 206, price: 0.30 }
      ];

      var bubbleColors = [
        c.blue, c.blue,
