const p=require('puppeteer');
(async()=>{
  const b=await p.launch({headless:'new',args:['--no-sandbox']});
  const pg=await b.newPage();
  pg.on('console',m=>console.log('CONSOLE:',m.text()));
  pg.on('pageerror',e=>console.log('PAGE_ERROR:',e.message));
  await pg.setViewport({width:1600,height:2263});
  await pg.goto('file:///app/output/poster.html',{waitUntil:'networkidle0',timeout:30000});
  await new Promise(r=>setTimeout(r,3000));
  const r2=await pg.evaluate(()=>{
    try { buildCharts(); return 'ok'; } catch(e) { return e.message + ' | ' + e.stack.split('\\n').slice(0,3).join(' | '); }
  });
  console.log('Manual build:', r2);
  await b.close();
})()
" 2>&1

