plugins: [{
  id: 'bubbleLabels',
  afterDatasetsDraw: function(chart) {
    var ctx2 = chart.ctx;
    ctx2.save();
    ctx2.font = '600 11px Inter';
    ctx2.textAlign = 'center';
    ctx2.fillStyle = c.textSec;

    var labels = [];
    chart.data.datasets.forEach(function(dataset, i) {
      var meta = chart.getDatasetMeta(i);
      if (meta.data[0]) {
        var pt = meta.data[0];
        var d = bubbleData[i];
        var shortName = d.name.replace(' Preview', '').replace(' (max)', '').replace(' (high)', '').replace(' (xhigh)', '').replace(' 0309 v2', '');
        labels.push({ x: pt.x, y: pt.y - pt.options.radius - 8, text: shortName, origY: pt.y - pt.options.radius - 8 });
      }
    });

    labels.sort(function(a, b) { return a.y - b.y; });
    for (var li = 1; li < labels.length; li++) {
      for (var lj = 0; lj < li; lj++) {
        if (Math.abs(labels[li].x - labels[lj].x) < 80 && Math.abs(labels[li].y - labels[lj].y) < 14) {
          labels[li].y = labels[lj].y + 14;
        }
      }
    }

    labels.forEach(function(lb) {
      ctx2.fillText(lb.text, lb.x, lb.y);
    });
    ctx2.restore();
  }
}, {

